previewCss:
.darma-loader-wiper-sweep {
  position: relative;
  width: 52px;
  height: 34px;
  border: 2px solid #c7d2fe;
  border-radius: 6px 6px 3px 3px;
  box-sizing: border-box;
  overflow: hidden;
}
.darma-loader-wiper-sweep i {
  position: absolute;
  bottom: 2px;
  left: 50%;
  width: 4px;
  height: 28px;
  margin-left: -2px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
  transform-origin: bottom center;
  animation: darma-loader-wiper-sweep-wipe 1.4s ease-in-out infinite;
}
.darma-loader-wiper-sweep i::after {
  content: "";
  position: absolute;
  top: 0;
  left: -3px;
  width: 10px;
  height: 5px;
  border-radius: 2px;
  background: var(--loader-color, #6366f1);
}
@keyframes darma-loader-wiper-sweep-wipe {
  0% { transform: rotate(-58deg); }
  50% { transform: rotate(58deg); }
  100% { transform: rotate(-58deg); }
}

